/* ---------- airline tails, for flight rows ---------- */
const TAIL: Record<string, [string, string]> = { NW: ['#1F3A5F', 'N'], CL: ['#0F7C80', 'C'], AU: ['#5B3FA8', 'A'] }
function tail(code: string) { const [c, l] = TAIL[code] || ['#17171A', code[0]]; return svg(sky(), `${cloud(40, 300, 1)}${cloud(330, 330, 0.9)}<path d="M-20 300 H330 Q400 300 400 340 Q400 380 330 380 H-20 Z" fill="${W}" ${st()}/><g fill="${SEA2}">${[40, 90, 140, 190, 240].map(x => `<circle cx="${x}" cy="335" r="9"/>`).join('')}</g><path d="M250 300 L330 90 H410 L370 300 Z" fill="${c}" ${st()}/><path d="M318 120 H404" stroke="${O}" stroke-width="12"/><text x="352" y="236" text-anchor="middle" font-family="Arial, Helvetica, sans-serif" font-weight="800" font-size="64" fill="${W}">${l}</text>`) }

/* ---------- build ---------- */
const tint = (hex: string, a = 0.78) => { const n = parseInt(hex.slice(1), 16), c = [n >> 16, (n >> 8) & 255, n & 255].map(v => Math.round(v + (255 - v) * a)); return '#' + c.map(v => v.toString(16).padStart(2, '0')).join('') }
const enc = (s: string) => 'data:image/svg+xml;utf8,' + encodeURIComponent(s)
const cache: Record<string, string> = {}
const mk = (key: string, f: () => string) => cache[key] || (cache[key] = enc(f()))
export function scene(key?: string): string | undefined {
  if (!key) return undefined
  const [ns, name] = key.includes(':') ? key.split(/:(.*)/s) : ['', key]
  if (ns === 'fly') return mk(key, () => flightTo(name))
  if (ns === 'tail') return mk(key, () => tail(name))
  if (ns === 'city') return mk(key, () => cityScene(name))
  if (ns === 'stay' && STAYS[name]) return mk(key, STAYS[name])
  if (ns === 'food' && FOOD[name]) return mk(key, FOOD[name])
  if (ns === 'do' && DO[name]) return mk(key, DO[name])
  if (ns === 'shop' && SHOP[name]) return mk(key, SHOP[name])
  if (ns === 'move' && MOVE[name]) return mk(key, MOVE[name])
  if (ns === 'gift') { const [cat, color] = name.split('|'); return mk(key, () => tile(tint(color || '#2E5E4E'), `<ellipse cx="240" cy="340" rx="150" ry="18" fill="${K}" opacity="0.08"/>${GIFT_ART[cat] || GIFT_ART.Homeware}`)) }
  if (ns === 'sub') { const [cat, color] = name.split('|'); return mk(key, () => tile(color ? tint(color, 0.82) : CREAM, SUB_ART[cat] || SUB_ART.Music)) }
  if (ns === 'money' && MONEY[name]) return mk(key, MONEY[name])
  return undefined
}
export const SCENE_KEYS = [
  ...Object.keys(CITY_LAND).map(c => 'fly:' + c), 'tail:NW', 'tail:CL', 'tail:AU', ...Object.keys(STAYS).map(k => 'stay:' + k), ...Object.keys(FOOD).map(k => 'food:' + k), ...Object.keys(DO).map(k => 'do:' + k),
  ...Object.keys(SHOP).map(k => 'shop:' + k), ...Object.keys(MOVE).map(k => 'move:' + k), ...Object.keys(GIFT_ART).map(k => 'gift:' + k + '|#2E5E4E'), ...Object.keys(SUB_ART).map(k => 'sub:' + k + '|#C0301C'), ...Object.keys(MONEY).map(k => 'money:' + k),
]
